1	/**
2	 * The branch panel: your edits, in the order you made them — and the six things
3	 * you can do to a claim.
4	 *
5	 * **A sequence, not a surprise.** Read as a list, the rule that a later edit
6	 * outranks an earlier supposition is obvious: you supposed the strait reopens,
7	 * then you added a strike, then you supposed the strike lands, and the strike's
8	 * arrow was added *after* the supposition, so it is live. Met instead as a number
9	 * that moved on its own, the same rule reads as a bug. So the sequence is on the
10	 * screen.
11	 *
12	 * **Edits are appended, never rewritten.** There is no way to edit an edit here,
13	 * and that is deliberate: the branch is the audit trail, and an audit trail you
14	 * can edit is not one.
15	 *
16	 * **The buttons build a branch, and the engine moves the numbers.** Pressing one
17	 * appends an edit and the panel shows it immediately; the whole branch is then
18	 * handed to the engine, which works the map's likelihoods through again and says
19	 * what moved. Nothing on this side works out a number — appending an edit is the
20	 * whole of what a button does.
21	 *
22	 * **One of the six says what it cannot do rather than doing it quietly.**
23	 * *Split this claim* is not built. It is not greyed out: a disabled control says
24	 * "not for you" and nothing else, and cannot even be asked about with the
25	 * keyboard.
26	 *
27	 * **One of the six needs the model, and only that one.** *Add a claim* sends the
28	 * sentence you type to the part of this product that drafts a whole claim — the
29	 * wording, the test that settles it, its judge, its date and what it started
30	 * from — and appends what comes back to the branch like any other edit. The
31	 * other five are arithmetic in the engine's pure core, which is why a reader
32	 * with no key still gets the whole multiverse at full fidelity.
33	 *
34	 * **Nothing here opens over the map.** No dialog, no scrim, nothing to dismiss:
35	 * the fields below appear inside this panel, beside the map, which stays live.
36	 */
37	
38	import { useState } from "react";
39	import type { components } from "../api/schema";
40	import { toDay } from "../graph/diff/days";
41	import { pushAsNumber, pushInWords } from "../graph/wires/encodings";
42	import type { BranchView, Edit, Selection, WorldView } from "../world";
43	import { AddAClaim } from "./AddAClaim";
44	import "./branchPanel.css";
45	
46	/**
47	 * The six buttons, word for word from the shared vocabulary's *Interface words*
48	 * table, and the badge each one earns.
49	 *
50	 * Copied, never paraphrased. The six operations keep their code names in the
51	 * code, in the wire format and in the spec, and **not one of those names ever
52	 * appears on screen.**
53	 */
54	const BUTTONS = {
55	  supposeTrue: "Suppose this is true",
56	  supposeFalse: "Suppose this is false",
57	  happened: "This happened",
58	  addClaim: "Add a claim",
59	  changePush: "Change this push",
60	  splitClaim: "Split this claim",
61	  ownNumber: "My own number",
62	} as const;
63	
64	/** How one edit reads in the list: which button made it, and what it was about. */
65	function editLine(edit: Edit, world: WorldView): { button: string; about: string; badge: string } {
66	  const words = (id: string): string => world.claims.find((claim) => claim.id === id)?.claim ?? id;
67	  switch (edit.op) {
68	    case "do":
69	      return {
70	        button: edit.value ? BUTTONS.supposeTrue : BUTTONS.supposeFalse,
71	        about: words(edit.target),
72	        badge: `Supposed · ${toDay(edit.at)}`,
73	      };
74	    case "observe":
75	      return {
76	        button: BUTTONS.happened,
77	        about: words(edit.target),
78	        badge: `Happened · ${toDay(edit.at)}`,
79	      };
80	    case "insert":
81	      return { button: BUTTONS.addClaim, about: edit.words, badge: "Added" };
82	    case "retune":
83	      return {
84	        button: BUTTONS.changePush,
85	        about:
86	          `You moved this arrow from ${pushAsNumber(edit.wasStrength)} to ` +
87	          `${pushAsNumber(edit.strength)} — ${pushInWords(edit.strength)}.`,
88	        badge: "Retuned",
89	      };
90	    case "refine":
91	      return { button: BUTTONS.splitClaim, about: words(edit.target), badge: "Split" };
92	    case "believe":
93	      return {
94	        button: BUTTONS.ownNumber,
95	        about: words(edit.target),
96	        badge: "",
97	      };
98	  }
99	}
100	
101	/** What the branch panel needs. */
102	export interface BranchPanelProps {
103	  /** Every branch on this map, in the order they arrived. */
104	  readonly branches: readonly BranchView[];
105	  /** Which branch is open, or `null` for the map as it was written. */
106	  readonly openId: string | null;
107	  /** The world on screen, so an edit can be read back in the claim's own words. */
108	  readonly world: WorldView;
109	  /** Open a branch, or go back to the map as it was written. */
110	  readonly onOpen: (id: string | null) => void;
111	  /** Start a new branch with this name. */
112	  readonly onFork: (label: string) => void;
113	  /** Whether the name field is open, because `B` opens it from the map. */
114	  readonly naming: boolean;
115	  /** Open or close the name field. */
116	  readonly onNaming: (open: boolean) => void;
117	}
118	
119	/** The branch panel. */
120	export function BranchPanel({
121	  branches,
122	  openId,
123	  world,
124	  onOpen,
125	  onFork,
126	  naming,
127	  onNaming,
128	}: BranchPanelProps) {
129	  const [name, setName] = useState("");
130	  const open = branches.find((branch) => branch.id === openId);
131	
132	  return (
133	    <section className="branch-panel" aria-label="Your branches">
134	      <h2 className="branch-panel__heading">Branches</h2>
135	
136	      <ul className="branch-panel__list">
137	        <li>
138	          <button
139	            className="branch-panel__branch"
140	            type="button"
141	            data-open={openId === null ? "yes" : "no"}
142	            onClick={() => onOpen(null)}
143	          >
144	            <span className="branch-panel__chip" data-hue="base" aria-hidden="true" />
145	            <span className="branch-panel__name">The map as it was written</span>
146	          </button>
147	        </li>
148	        {branches.map((branch) => (
149	          <li key={branch.id}>
150	            <button
151	              className="branch-panel__branch"
152	              type="button"
153	              data-open={openId === branch.id ? "yes" : "no"}
154	              onClick={() => onOpen(branch.id)}
155	            >
156	              {/* A branch's hue is on its chip and its lane and nowhere else, and
157	                  the chip always carries the branch's name — so which branch you
158	                  are in is readable with no colour at all. */}
159	              <span className="branch-panel__chip" data-hue={branch.hue} aria-hidden="true" />
160	              <span className="branch-panel__name">{branch.label}</span>
161	              <span className="branch-panel__count">
162	                {branch.edits.length === 1 ? "1 edit" : `${branch.edits.length} edits`}
163	              </span>
164	            </button>
165	          </li>
166	        ))}
167	      </ul>
168	
169	      {naming ? (
170	        <form
171	          className="branch-panel__naming"
172	          onSubmit={(event) => {
173	            event.preventDefault();
174	            const label = name.trim();
175	            if (label !== "") {
176	              onFork(label);
177	              setName("");
178	              onNaming(false);
179	            }
180	          }}
181	        >
182	          <label className="branch-panel__field-label" htmlFor="branch-name">
183	            What is this branch called? An unnamed branch is unusable once there are three.
184	          </label>
185	          <input
186	            className="branch-panel__field"
187	            id="branch-name"
188	            value={name}
189	            // biome-ignore lint/a11y/noAutofocus: the reader pressed B to open this field and the next thing they will do is type into it; sending focus anywhere else is a keystroke thrown away.
190	            autoFocus
191	            onChange={(event) => setName(event.target.value)}
192	          />
193	          <div className="branch-panel__field-actions">
194	            <button className="branch-panel__go" type="submit">
195	              Start this branch
196	            </button>
197	            <button
198	              className="branch-panel__cancel"
199	              type="button"
200	              onClick={() => {
201	                setName("");
202	                onNaming(false);
203	              }}
204	            >
205	              Not now
206	            </button>
207	          </div>
208	        </form>
209	      ) : (
210	        <button className="branch-panel__fork" type="button" onClick={() => onNaming(true)}>
211	          Start a branch
212	        </button>
213	      )}
214	
215	      {open === undefined ? (
216	        // Where the numbers on the unedited map came from — and there are two
217	        // answers, told apart by the one thing that says whether anything was
218	        // worked out: whether the world reports how many versions of the map
219	        // were run. The engine's answer and the stored example's own numbers are
220	        // different claims about the world, and a screen that said the same
221	        // sentence over both would be making the weaker one silently.
222	        <p className="branch-panel__none">
223	          {world.versions === undefined
224	            ? "Nothing has been edited. The map above is exactly as it was written, and every " +
225	              "number on it is the one the stored example carries — nothing has worked one out."
226	            : "Nothing has been edited. The map above is exactly as it was written, and every " +
227	              "number on it was worked out by the engine from that map with nothing done to it."}
228	        </p>
229	      ) : (
230	        <ol className="branch-panel__edits">
231	          {open.edits.map((edit, index) => {
232	            const line = editLine(edit, world);
233	            return (
234	              // biome-ignore lint/suspicious/noArrayIndexKey: a branch is append-only — no edit is ever rewritten, removed or reordered — so an edit's place in the list is a stable name for it, and it is the name the panel prints beside it.
235	              <li className="branch-panel__edit" key={`${index}-${line.button}`}>
236	                <span className="branch-panel__number">{index + 1}</span>
237	                <span className="branch-panel__about">
238	                  <span className="branch-panel__button-name">{line.button}</span>
239	                  <span className="branch-panel__subject">{line.about}</span>
240	                </span>
241	                {line.badge === "" ? (
242	                  <span className="branch-panel__no-badge">
243	                    no badge — the three-up belief chip is the badge
244	                  </span>
245	                ) : (
246	                  <span className="branch-panel__badge">{line.badge}</span>
247	                )}
248	              </li>
249	            );
250	          })}
251	        </ol>
252	      )}
253	    </section>
254	  );
255	}
256	
257	/** What the six-button panel needs. */
258	export interface InterventionPanelProps {
259	  /** The world on screen. */
260	  readonly world: WorldView;
261	  /**
262	   * The open branch in the engine's own shape, when it can be written down.
263	   *
264	   * **Add a claim needs it and nothing else on this panel does.** The route
265	   * drafts and judges the new claim against the map with the branch folded on —
266	   * which is the map the reader is looking at — so a claim that contradicts an
267	   * edit made two minutes ago comes back refused in the validator's own
268	   * sentence rather than accepted and then breaking the branch it is added to.
269	   * Absent when the branch cannot be written down in full, which is exactly
270	   * when there is nothing honest to send.
271	   */
272	  readonly branch?: components["schemas"]["Branch"];
273	  /** What the map is open on: the claim or the arrow the buttons act on. */
274	  readonly selection: Selection;
275	  /** Append an edit to the open branch. */
276	  readonly onEdit: (edit: Edit) => void;
277	  /** Close the panel. */
278	  readonly onClose: () => void;
279	}
280	
281	/**
282	 * The six things you can do to a claim, in a panel beside the map.
283	 *
284	 * Never a pop-up: it appears in the panel, the map keeps drawing beside it, and
285	 * closing it loses nothing because nothing is left half-done.
286	 */
287	export function InterventionPanel({
288	  world,
289	  branch,
290	  selection,
291	  onEdit,
292	  onClose,
293	}: InterventionPanelProps) {
294	  const [ownNumber, setOwnNumber] = useState(false);
295	  const [reading, setReading] = useState({ p: "", lo: "", hi: "" });
296	  const [pushing, setPushing] = useState(false);
297	  const [adding, setAdding] = useState(false);
298	  const [push, setPush] = useState("");
299	  const [said, setSaid] = useState<string | null>(null);
300	
301	  const claim =
302	    selection?.kind === "claim" ? world.claims.find((one) => one.id === selection.id) : undefined;
303	  const wire =
304	    selection?.kind === "wire" ? world.links.find((one) => one.id === selection.id) : undefined;
305	
306	  const say = (line: string) => setSaid(line);
307	
308	  /**
309	   * Nothing here is ever disabled. A greyed-out button says "not for you" and
310	   * nothing else — and it is unreachable by keyboard, which makes it a control a
311	   * reader cannot even ask about. So a button with nothing to act on says what it
312	   * needs instead.
313	   */
314	  const needsAClaim = (): boolean => {
315	    if (claim !== undefined) {
316	      return false;
317	    }
318	    say(
319	      "Choose a claim on the map first — click it, or reach it with the keyboard and the panel " +
320	        "opens on it.",
321	    );
322	    return true;
323	  };
324	
325	  return (
326	    <section className="intervene" aria-label="Change this claim">
327	      <header className="intervene__head">
328	        <h2 className="intervene__heading">Change this</h2>
329	        <button className="intervene__close" type="button" onClick={onClose}>
330	          Done
331	        </button>
332	      </header>
333	
334	      <p className="intervene__subject">
335	        {claim !== undefined
336	          ? claim.claim
337	          : wire !== undefined
338	            ? "The arrow you have selected on the map."
339	            : "Choose a claim or an arrow on the map first — click it, or reach it with the keyboard."}
340	      </p>
341	
342	      <div className="intervene__buttons">
343	        <button
344	          className="intervene__button"
345	          type="button"
346	          onClick={() => {
347	            if (needsAClaim() || claim === undefined) {
348	              return;
349	            }
350	            onEdit({ op: "do", target: claim.id, value: true, at: world.today });
351	            say("Take this as given, and do not tell me what caused it.");
352	          }}
353	        >
354	          {BUTTONS.supposeTrue}
355	        </button>
356	        <button
357	          className="intervene__button"
358	          type="button"
359	          onClick={() => {
360	            if (needsAClaim() || claim === undefined) {
361	              return;
362	            }
363	            onEdit({ op: "do", target: claim.id, value: false, at: world.today });
364	            say("Take this as given, and do not tell me what caused it.");
365	          }}
366	        >
367	          {BUTTONS.supposeFalse}
368	        </button>
369	        <button
370	          className="intervene__button"
371	          type="button"
372	          onClick={() => {
373	            if (needsAClaim() || claim === undefined) {
374	              return;
375	            }
376	            onEdit({ op: "observe", target: claim.id, value: true, at: world.today });
377	            say("This is news — what came before it is read again, not only what comes after.");
378	          }}
379	        >
380	          {BUTTONS.happened}
381	        </button>
382	        {/* **Add a claim** is the one of the six that needs the model, and it
383	            is now connected: the sentence goes to the one route that drafts a
384	            claim, the same rules every proposal passes check what comes back,
385	            and the edit is appended to the branch like any other. It is the same
386	            control, with the same words and the same refusals, on a stored map
387	            and on one that has just built itself.
388	
389	            It is a field rather than a button because a claim starts with a
390	            sentence somebody types, and the other five act on what is already
391	            selected. */}
392	        <button
393	          className="intervene__button"
394	          type="button"
395	          onClick={() => setAdding((was) => !was)}
396	          aria-expanded={adding}
397	        >
398	          {BUTTONS.addClaim}
399	          <span className="intervene__hint">…but this also happens</span>
400	        </button>
401	        <button
402	          className="intervene__button"
403	          type="button"
404	          onClick={() => {
405	            if (wire === undefined) {
406	              say(
407	                "Choose an arrow on the map first. This changes one number on one arrow, and " +
408	                  "nothing else about it.",
409	              );
410	              return;
411	            }
412	            setPush(`${wire.strength}`);
413	            setPushing((was) => !was);
414	          }}
415	        >
416	          {BUTTONS.changePush}
417	        </button>
418	        {adding ? (
419	          <AddAClaim
420	            baseId={world.baseId}
421	            {...(branch === undefined ? {} : { branch })}
422	            andThen="It is on your branch, like every other edit."
423	            onDrafted={(drafted) => {
424	              setAdding(false);
425	              onEdit({
426	                op: "insert",
427	                claimId: drafted.proposition.id,
428	                words: drafted.proposition.claim,
429	                arrows: drafted.links.map((link) => ({
430	                  id: link.id,
431	                  source: link.source,
432	                  target: link.target,
433	                })),
434	                drafted,
435	              });
436	            }}
437	          />
438	        ) : null}
439	        <button
440	          className="intervene__button"
441	          type="button"
442	          data-live="no"
443	          onClick={() =>
444	            say(
445	              "Splitting a claim into finer claims that add back up to it is not built yet. " +
446	                "Nothing here pretends otherwise, and no edit was recorded.",
447	            )
448	          }
449	        >
450	          {BUTTONS.splitClaim}
451	          <span className="intervene__hint">not yet built</span>
452	        </button>
453	        <button
454	          className="intervene__button"
455	          type="button"
456	          onClick={() => {
457	            if (needsAClaim()) {
458	              return;
459	            }
460	            setOwnNumber((was) => !was);
461	          }}
462	        >
463	          {BUTTONS.ownNumber}
464	          <span className="intervene__hint">beside the model's, never averaged with it</span>
465	        </button>
466	      </div>
467	
468	      {pushing && wire !== undefined ? (
469	        <form
470	          className="intervene__form"
471	          onSubmit={(event) => {
472	            event.preventDefault();
473	            const moved = Number(push);
474	            if (!Number.isFinite(moved)) {
475	              return;
476	            }
477	            onEdit({
478	              op: "retune",
479	              link: wire.id,
480	              strength: moved,
481	              wasStrength: wire.strength,
482	            });
483	            setPushing(false);
484	            say(
485	              `You moved this arrow from ${pushAsNumber(wire.strength)} to ` +
486	                `${pushAsNumber(moved)} — ${pushInWords(moved)}. Nothing else about the arrow ` +
487	                `changed.`,
488	            );
489	          }}
490	        >
491	          <label className="intervene__label" htmlFor="new-push">
492	            {`How hard does this arrow push? It is ${pushAsNumber(wire.strength)} — ` +
493	              `${pushInWords(wire.strength)}. A negative number pushes the other way.`}
494	          </label>
495	          <input
496	            className="intervene__field"
497	            id="new-push"
498	            inputMode="decimal"
499	            value={push}
500	            onChange={(event) => setPush(event.target.value)}
501	          />
502	          {/* Not the button's own words again: two things called *Change this
503	              push* on one panel is two things a reader has to tell apart. */}
504	          <button className="intervene__go" type="submit">
505	            Change it to that
506	          </button>
507	        </form>
508	      ) : null}
509	
510	      {ownNumber && claim !== undefined ? (
511	        <form
512	          className="intervene__form"
513	          onSubmit={(event) => {
514	            event.preventDefault();
515	            const p = Number(reading.p);
516	            const lo = Number(reading.lo);
517	            const hi = Number(reading.hi);
518	            if (!(lo >= 0 && lo <= p && p <= hi && hi <= 1)) {
519	              say(
520	                "A likelihood runs from 0 to 1, and the range has to hold the number: the bottom " +
521	                  "at or below it, the top at or above it.",
522	              );
523	              return;
524	            }
525	            onEdit({ op: "believe", target: claim.id, belief: { p, lo, hi } });
526	            setOwnNumber(false);
527	            setReading({ p: "", lo: "", hi: "" });
528	            say(
529	              "Your number now sits beside the model's and the market's on that tile. It is never " +
530	                "averaged with either of them, and it is not pushed through the map.",
531	            );
532	          }}
533	        >
534	          <label className="intervene__label" htmlFor="own-p">
535	            Your likelihood, and the range that says how sure you are of it. Between 0 and 1.
536	          </label>
537	          <div className="intervene__three">
538	            <input
539	              className="intervene__field"
540	              id="own-p"
541	              inputMode="decimal"
542	              placeholder="likelihood"
543	              value={reading.p}
544	              onChange={(event) => setReading((was) => ({ ...was, p: event.target.value }))}
545	            />
546	            <input
547	              className="intervene__field"
548	              aria-label="the bottom of your range"
549	              inputMode="decimal"
550	              placeholder="bottom"
551	              value={reading.lo}
552	              onChange={(event) => setReading((was) => ({ ...was, lo: event.target.value }))}
553	            />
554	            <input
555	              className="intervene__field"
556	              aria-label="the top of your range"
557	              inputMode="decimal"
558	              placeholder="top"
559	              value={reading.hi}
560	              onChange={(event) => setReading((was) => ({ ...was, hi: event.target.value }))}
561	            />
562	          </div>
563	          <button className="intervene__go" type="submit">
564	            Put this number on the claim
565	          </button>
566	        </form>
567	      ) : null}
568	
569	      <p className="intervene__said">
570	        {said ??
571	          "Every button here appends an edit to a branch and shows it. The branch then goes to " +
572	            "the engine, which works the map's numbers through again and says what moved — " +
573	            "nothing on this side of the screen works one out."}
574	      </p>
575	    </section>
576	  );
577	}
