1	/**
2	 * The screen a stored map is read and edited on.
3	 *
4	 * The map fills it, the panel beside it answers *why is this number what it
5	 * is*, and every edit a reader makes goes onto a branch of their own rather
6	 * than onto the map. Nothing here works a number out: the engine is asked for
7	 * the map with the branch folded on, and while it is being asked the slot says
8	 * so in words rather than showing a stale figure or a spinner.
9	 *
10	 * **The screen around the map is not here.** It is `MapFrame`, shared with the
11	 * map that builds itself: a bar with the way back, the stage, the panel in its
12	 * frame, one polite line said out loud and the origin strip at the foot. The
13	 * two screens were written twice and drifted the moment either was improved —
14	 * the panel's frame landed on one a round before the other, the error boundary
15	 * on one and never on the other.
16	 */
17	
18	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
19	import { branchAnnouncement } from "../a11y/announcement";
20	import { outlineOf } from "../a11y/sentences";
21	import { RefusedBranch } from "../api/client";
22	import { MapCanvas } from "../graph/Canvas";
23	import { bothPaintings, type Engine, railRows } from "../graph/diff/branchWorld";
24	import { endings, NO_SUMMARY_YET } from "../graph/diff/endings";
25	import { roomFor } from "../graph/geometry";
26	import type { MapKeys } from "../keyboard/useMapKeys";
27	import {
28	  type Absence,
29	  appendEdit,
30	  type BranchView,
31	  type DiffView,
32	  type Edit,
33	  forkBranch,
34	  type Known,
35	  type LinkView,
36	  openBranch,
37	  type Ranged,
38	  type Reason,
39	  type Selection,
40	  type WorldSource,
41	  type WorldView,
42	  workshopOf,
43	} from "../world";
44	import { absence } from "../world/absence";
45	import { asOneSentence } from "../world/failures";
46	import { BranchPanel, InterventionPanel } from "./BranchPanel";
47	import { type Command, CommandPalette } from "./CommandPalette";
48	import { DeltaRail } from "./DeltaRail";
49	import { Inspector } from "./Inspector";
50	import { MapFrame } from "./MapFrame";
51	import { Outline } from "./Outline";
52	import { Refusal } from "./Refusal";
53	import { ShortcutsSheet } from "./ShortcutsSheet";
54	
55	/** How long the wires take to arrive, column by column, before the map settles. */
56	const WAVE_SETTLES_AFTER = 1200;
57	
58	/**
59	 * What stands where a likelihood would go while the engine is being asked for
60	 * one.
61	 *
62	 * The shared vocabulary has three ways of saying a number is not there, and
63	 * this is the third of them — *nothing has been computed* — because that is
64	 * exactly what is true while a question is in flight: the engine has been asked
65	 * and has not answered, so nothing has worked this number through the map
66	 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
67	 * on screen keeps its shape, the slots that will move say why they are empty,
68	 * and the line under the map says what has been asked for and where.
69	 */
70	const WHILE_ASKING: Absence = absence(
71	  "no_engine",
72	  "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
73	    "has not answered. Nothing has worked this number through the map yet.",
74	);
75	
76	/**
77	 * What stands where a likelihood would go when the engine **refused** the
78	 * branch.
79	 *
80	 * Not "no engine yet": the engine is there and it answered — it said the branch
81	 * does not fit the map, and it said why. The words have to be true of that, and
82	 * the vocabulary's first three rows are all about a number nobody has worked out
83	 * rather than one that could not be. So there is a **fourth row** — *the engine
84	 * refused the branch these numbers would come from* → **not worked out** — and a
85	 * kind of its own to go with it, because "nothing has run yet" invites waiting
86	 * and "the engine turned this down" invites repairing what it turned down.
87	 */
88	const REFUSED: Absence = absence(
89	  "refused",
90	  "The engine would not work this map out from this branch: the branch does not fit the map. " +
91	    "Every reason is beside the map, and nothing on the map has changed.",
92	);
93	
94	/**
95	 * What stands there when the engine could not be reached at all.
96	 *
97	 * **Not a refusal**, and the difference is the whole of why the two are separate
98	 * kinds. A refusal is an answer: the engine looked, said no, and said why, and
99	 * it will say the same thing until the branch is repaired. This is one attempt
100	 * that did not come back — the engine is there and it was asked — and it stops
101	 * being true the moment the reader asks again. So it takes the kind that is
102	 * never kept, and its reason says what to do about it.
103	 */
104	function unreachable(reason: string): Absence {
105	  return absence(
106	    "ask_failed",
107	    `${reason} Nothing on the map has changed; opening the branch again asks once more.`,
108	  );
109	}
110	
111	/**
112	 * Everything the engine has said about the branch that is open, and whether it
113	 * has said it yet.
114	 */
115	type Answered =
116	  | { at: "asking" }
117	  | { at: "answered"; computed: { now: WorldView; change: DiffView } }
118	  | { at: "refused"; reasons: readonly Reason[] }
119	  | { at: "failed"; reason: string }
120	  | { at: "nothing-open" };
121	
122	/**
123	 * Where the engine has got to, in the one shape the picture reads.
124	 *
125	 * Every state but *nothing is open* reserves the room an answer will take and
126	 * says why it is not there yet, so the map is the same size before and after the
127	 * answer lands and nothing on it jumps.
128	 */
129	function engineState(answer: Answered): Engine | undefined {
130	  switch (answer.at) {
131	    case "answered":
132	      return { at: "answered", now: answer.computed.now, change: answer.computed.change };
133	    case "asking":
134	      return { at: "waiting", absence: WHILE_ASKING };
135	    case "refused":
136	      return { at: "waiting", absence: REFUSED };
137	    case "failed":
138	      return { at: "waiting", absence: unreachable(answer.reason) };
139	    case "nothing-open":
140	      return undefined;
141	  }
142	}
143	
144	/** Turn whatever the engine threw into either a list of reasons or one sentence. */
145	function asAnswer(reason: unknown): Answered {
146	  if (reason instanceof RefusedBranch) {
147	    return { at: "refused", reasons: reason.reasons };
148	  }
149	  return { at: "failed", reason: asOneSentence(reason) };
150	}
151	
152	/**
153	 * The map, the panel beside it, and everything you can do to both.
154	 *
155	 * Three things live here rather than inside the map, because all three are about
156	 * the whole screen rather than about the picture: which branch is open, which of
157	 * the two worlds is painted, and what the keyboard is on.
158	 */
159	export function MapScreen({
160	  base,
161	  branches,
162	  source,
163	  insteadOfTheEngine,
164	  onLeave,
165	}: {
166	  base: WorldView;
167	  branches: readonly BranchView[];
168	  /** Where a branch's world, its difference and an arrow's number are asked for. */
169	  source: WorldSource;
170	  /** Why this map is the stored example rather than the engine's, or nothing. */
171	  insteadOfTheEngine: string | null;
172	  onLeave: () => void;
173	}) {
174	  const [shop, setShop] = useState(() => workshopOf(branches));
175	  const [showing, setShowing] = useState<"now" | "before">("now");
176	  const [selection, setSelection] = useState<Selection>(null);
177	  const [focused, setFocused] = useState<string | null>(null);
178	  const [dock, setDock] = useState<"panel" | "outline" | "away">("panel");
179	  const [onlyColumn, setOnlyColumn] = useState<{
180	    layer: number;
181	    claims: readonly string[];
182	  } | null>(null);
183	  const [overlay, setOverlay] = useState<"palette" | "sheet" | null>(null);
184	  const [intervening, setIntervening] = useState(false);
185	  const [naming, setNaming] = useState(false);
186	  const [status, setStatus] = useState(
187	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
188	  );
189	  const [arriving, setArriving] = useState(true);
190	  const lastBranch = useRef<string | null>(null);
191	
192	  const open = shop.branches.find((branch) => branch.id === shop.openId);
193	
194	  // What the engine says about the branch that is open. It is asked again
195	  // whenever the branch changes — which is what makes the six buttons move
196	  // numbers: pressing one appends an edit, and the whole branch goes back.
197	  const [answer, setAnswer] = useState<Answered>({ at: "nothing-open" });
198	  useEffect(() => {
199	    if (open === undefined) {
200	      setAnswer({ at: "nothing-open" });
201	      return;
202	    }
203	    let stillWanted = true;
204	    setAnswer({ at: "asking" });
205	    Promise.all([
206	      source.readWorld({ baseId: base.baseId, branch: open }),
207	      source.readDiff({ baseId: base.baseId, branch: open }),
208	    ]).then(
209	      ([now, change]) => {
210	        if (stillWanted) {
211	          setAnswer({ at: "answered", computed: { now, change } });
212	        }
213	      },
214	      (failure: unknown) => {
215	        if (stillWanted) {
216	          setAnswer(asAnswer(failure));
217	        }
218	      },
219	    );
220	    return () => {
221	      // An answer to a question the reader has moved on from is thrown away
222	      // rather than drawn: a map that flickers back to an older branch because
223	      // a slower request finished last is a map nobody can trust.
224	      stillWanted = false;
225	    };
226	    // The branch itself is what this hangs on, and that is enough: appending an
227	    // edit hands back a new branch rather than changing the one that was there
228	    // — a branch is an audit trail and nothing rewrites one — so every press of
229	    // a button is a new question here, and nothing else is.
230	  }, [source, base.baseId, open]);
231	
232	  // Held still between renders, because both paintings of the map hang on it: a
233	  // fresh object every render would lay the whole map out again on every keypress
234	  // for an answer that has not changed.
235	  const engine = useMemo(() => engineState(answer), [answer]);
236	  const computed = answer.at === "answered" ? answer.computed : undefined;
237	
238	  // The numbers on the arrows, one at a time, kept once they arrive. Each one
239	  // costs a whole extra run of the map, so it is asked for when a reader selects
240	  // that arrow and never again for the same branch, seed and arrow.
241	  const [wireNumbers, setWireNumbers] = useState<ReadonlyMap<string, Known<Ranged>>>(new Map());
242	  // The last ask that did not come back, which is shown and never kept. A
243	  // failure is a fact about one attempt, not about the number: keeping it would
244	  // mean the reader who selects the arrow again after the server comes back is
245	  // told for the rest of the session that it cannot be worked out.
246	  const [wireFailed, setWireFailed] = useState<{ key: string; absence: Absence } | undefined>();
247	  const paintings = useMemo(
248	    () => (open === undefined ? null : bothPaintings(base, open, engine)),
249	    [base, open, engine],
250	  );
251	
252	  const painted = paintings === null ? base : showing === "now" ? paintings.now : paintings.before;
253	  const seed = painted.seed;
254	
255	  /**
256	   * The branch the map in front is drawn from — nothing, when the map in front
257	   * is the one as it was written.
258	   *
259	   * Flipping to "as it was written" puts the base map on screen, and an arrow's
260	   * number worked out under a branch is not a number about that map. This is the
261	   * branch every arrow number on this screen is asked for and named by, so the
262	   * question asked and the map drawn can never come apart.
263	   */
264	  const shownBranch = paintings === null || showing === "before" ? undefined : open;
265	
266	  /**
267	   * What names one arrow's number: which branch, how far that branch has got,
268	   * which seed, which arrow.
269	   *
270	   * The edit count is in the name because a branch's `id` outlives its edits: an
271	   * edit appends to the branch and hands back a new one with the same id, so a
272	   * name without the count would hand a reader the number worked out before
273	   * their edit. Counting is enough to tell two branches apart because edits are
274	   * only ever appended — `appendEdit` is the one function that touches them, and
275	   * there is no undo (INV-workbench.49).
276	   */
277	  const wireKey = useCallback(
278	    (linkId: string) => {
279	      const whose =
280	        shownBranch === undefined ? "as-written" : `${shownBranch.id}@${shownBranch.edits.length}`;
281	      return `${whose}:${seed ?? "no-seed"}:${linkId}`;
282	    },
283	    [shownBranch, seed],
284	  );
285	
286	  // The map as it is drawn: the world above, with any arrow number already
287	  // fetched put back on its own arrow.
288	  const world = useMemo((): WorldView => {
289	    if (wireNumbers.size === 0 && wireFailed === undefined) {
290	      return painted;
291	    }
292	    return {
293	      ...painted,
294	      links: painted.links.map((link): LinkView => {
295	        const key = wireKey(link.id);
296	        const asked = wireNumbers.get(key);
297	        if (asked !== undefined) {
298	          return { ...link, conditional: asked };
299	        }
300	        return wireFailed?.key === key
301	          ? { ...link, conditional: { absence: wireFailed.absence } }
302	          : link;
303	      }),
304	    };
305	  }, [painted, wireNumbers, wireFailed, wireKey]);
306	
307	  /**
308	   * One box per claim, tall enough for whichever of the two paintings needs more
309	   * room — a claim grows badges when an edit touched it. Reserving the taller box
310	   * is what lets the union be laid out once and painted twice with nothing
311	   * moving.
312	   */
313	  const heights = useMemo(() => {
314	    if (paintings === null) {
315	      return undefined;
316	    }
317	    const reserved = new Map<string, number>();
318	    for (const side of [paintings.now, paintings.before]) {
319	      for (const claim of side.claims) {
320	        reserved.set(claim.id, Math.max(reserved.get(claim.id) ?? 0, roomFor(claim)));
321	      }
322	    }
323	    return reserved;
324	  }, [paintings]);
325	
326	  // The endings the edit reaches. With the engine, its own ranked rows, in its
327	  // own order; without it, the reachable endings in map order, and the rail
328	  // says on its own face which of the two it is showing.
329	  const rows = useMemo(
330	    () =>
331	      computed !== undefined
332	        ? railRows(paintings?.now ?? base, computed.change)
333	        : paintings === null
334	          ? []
335	          : endings(paintings.now),
336	    [computed, paintings, base],
337	  );
338	  const outline = useMemo(() => outlineOf(world), [world]);
339	
340	  // What the branch did, said out loud for a reader who is not looking at the
341	  // picture. It is said twice, because the two halves arrive at different
342	  // moments: the shape the instant the branch opens, and the counts when the
343	  // engine answers. The live region is polite, so the second line waits for a
344	  // pause rather than cutting across the first.
345	  const announcement = useMemo(
346	    () => (paintings === null ? "" : branchAnnouncement(paintings.now, computed?.change)),
347	    [paintings, computed],
348	  );
349	
350	  // One arrow's own number, asked for when the reader selects that arrow and
351	  // kept afterwards. It is fetched here rather than by the wire because no
352	  // component in this product talks to the network, and because the answer
353	  // belongs to the whole screen: the panel and the plate on the wire read the
354	  // same one.
355	  useEffect(() => {
356	    if (selection?.kind !== "wire") {
357	      return;
358	    }
359	    const key = wireKey(selection.id);
360	    if (wireNumbers.has(key)) {
361	      return;
362	    }
363	    let stillWanted = true;
364	    source.readConditional({ baseId: base.baseId, branch: shownBranch, linkId: selection.id }).then(
365	      (slot) => {
366	        if (stillWanted) {
367	          setWireNumbers((was) => new Map(was).set(key, slot));
368	          setWireFailed((was) => (was?.key === key ? undefined : was));
369	        }
370	      },
371	      (failure: unknown) => {
372	        // Shown, and not filed with the answers. The engine is there and it was
373	        // asked — what is missing is this one attempt's reply, which is a
374	        // different thing from "nothing has worked this number out", and which
375	        // stops being true the moment the reader asks again.
376	        if (stillWanted) {
377	          setWireFailed({
378	            key,
379	            absence: absence(
380	              "ask_failed",
381	              `${asOneSentence(failure)} Select this arrow again to ask once more.`,
382	            ),
383	          });
384	        }
385	      },
386	    );
387	    return () => {
388	      stillWanted = false;
389	    };
390	  }, [selection, source, base.baseId, shownBranch, wireKey, wireNumbers]);
391	
392	  // A branch has just been opened or made. Three things follow, in this order:
393	  // the map says out loud what the branch did, the wires arrive again in causal
394	  // order, and — because creating a claim moves focus to it — the keyboard lands
395	  // on the claim the branch added, so the view frames the thing you just made
396	  // rather than leaving you to hunt for it.
397	  useEffect(() => {
398	    if (shop.openId === lastBranch.current) {
399	      return;
400	    }
401	    lastBranch.current = shop.openId;
402	    setShowing("now");
403	    setArriving(true);
404	    if (paintings === null) {
405	      return;
406	    }
407	    const arrived = paintings.now.claims.find((claim) => claim.diff === "added");
408	    if (arrived !== undefined) {
409	      setFocused(arrived.id);
410	      setSelection({ kind: "claim", id: arrived.id });
411	      setStatus(`your edit added this claim · ${arrived.claim}`);
412	    }
413	  }, [shop.openId, paintings]);
414	
415	  // The wave settles on its own clock, and on nothing else.
416	  //
417	  // **It has to be its own effect.** The one above runs again whenever the
418	  // picture changes — and the picture changes when the engine answers, which is
419	  // a moment or two after a branch is opened. A timer started up there would be
420	  // cleared by that second run and never started again, and the map would stay
421	  // mid-arrival for ever, which is to say invisible.
422	  useEffect(() => {
423	    if (!arriving) {
424	      return;
425	    }
426	    const settles = window.setTimeout(() => setArriving(false), WAVE_SETTLES_AFTER);
427	    return () => window.clearTimeout(settles);
428	  }, [arriving]);
429	
430	  const edit = useCallback((made: Edit) => {
431	    setShop((was) =>
432	      appendEdit(was.openId === null ? forkBranch(was, "Your own branch") : was, made),
433	    );
434	  }, []);
435	
436	  const keys: MapKeys = useMemo(
437	    () => ({
438	      intervene: () => {
439	        setDock("panel");
440	        setIntervening(true);
441	      },
442	      branch: () => {
443	        setDock("panel");
444	        setNaming(true);
445	      },
446	      flipWorlds: () => {
447	        if (paintings === null) {
448	          setStatus("there is nothing to flip to — no branch is open");
449	          return;
450	        }
451	        setShowing((was) => {
452	          const next = was === "now" ? "before" : "now";
453	          setStatus(
454	            next === "now"
455	              ? "the map with your edits"
456	              : "the map as it was written, with what your branch adds drawn faint",
457	          );
458	          return next;
459	        });
460	      },
461	      outline: () =>
462	        setDock((was) => {
463	          setOnlyColumn(null);
464	          return was === "outline" ? "panel" : "outline";
465	        }),
466	      panel: () => setDock((was) => (was === "away" ? "panel" : "away")),
467	      palette: () => setOverlay("palette"),
468	    }),
469	    [paintings],
470	  );
471	
472	  // ⌘K, ? and Escape work wherever you are on the screen, not only on the map,
473	  // because two of them are how you find out what the others do.
474	  useEffect(() => {
475	    const onKey = (event: KeyboardEvent): void => {
476	      const target = event.target as HTMLElement | null;
477	      const typing =
478	        target?.tagName === "INPUT" ||
479	        target?.tagName === "TEXTAREA" ||
480	        target?.isContentEditable === true;
481	      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
482	        event.preventDefault();
483	        setOverlay((was) => (was === "palette" ? null : "palette"));
484	        return;
485	      }
486	      if (event.key === "Escape") {
487	        setOverlay(null);
488	        setIntervening(false);
489	        setNaming(false);
490	        return;
491	      }
492	      if (event.key === "?" && !typing) {
493	        event.preventDefault();
494	        setOverlay((was) => (was === "sheet" ? null : "sheet"));
495	      }
496	    };
497	    window.addEventListener("keydown", onKey);
498	    return () => window.removeEventListener("keydown", onKey);
499	  }, []);
500	
501	  const commands: Command[] = useMemo(() => {
502	    const made: Command[] = [
503	      {
504	        name: "The map as it was written",
505	        does: "Close the branch. Also the first row of the branch panel.",
506	        run: () => setShop((was) => openBranch(was, null)),
507	      },
508	      ...shop.branches.map((branch) => ({
509	        name: `Open the branch: ${branch.label}`,
510	        does: `${branch.edits.length} edits. Also a row in the branch panel.`,
511	        run: () => setShop((was) => openBranch(was, branch.id)),
512	      })),
513	      {
514	        name: "Flip between the two maps",
515	        does: "The same as pressing Space on the map. A hard switch, never a fade.",
516	        run: keys.flipWorlds,
517	      },
518	      {
519	        name: "Change this claim",
520	        does: "The six things you can do to it. The same as pressing E on the map.",
521	        run: keys.intervene,
522	      },
523	      {
524	        name: "Start a branch",
525	        does: "The same as pressing B on the map, and as the button in the branch panel.",
526	        run: keys.branch,
527	      },
528	      {
529	        name: "Read the map as a list",
530	        does: "The same as pressing O. Every claim, one sentence each.",
531	        run: () => {
532	          setOnlyColumn(null);
533	          setDock("outline");
534	        },
535	      },
536	      {
537	        name: "Show or hide the panel beside the map",
538	        does: "The same as pressing P, when you want the whole width for the map.",
539	        run: keys.panel,
540	      },
541	      {
542	        name: "Every key, on one sheet",
543	        does: "The same as pressing the question mark.",
544	        run: () => setOverlay("sheet"),
545	      },
546	      {
547	        name: "Back to the launchpad",
548	        does: "The same as the link at the top left.",
549	        run: onLeave,
550	      },
551	    ];
552	    return made;
553	  }, [shop.branches, keys, onLeave]);
554	
555	  const pick = useCallback((id: string) => {
556	    setFocused(id);
557	    setSelection({ kind: "claim", id });
558	  }, []);
559	
560	  const THE_PANEL = (
561	    <>
562	      {dock === "outline" ? (
563	        <Outline
564	          items={outline}
565	          onPick={pick}
566	          focused={focused}
567	          {...(onlyColumn === null
568	            ? {}
569	            : {
570	                only: new Set(onlyColumn.claims),
571	                filter:
572	                  `Only the claims in column ${onlyColumn.layer}, which is what the ` +
573	                  `collapsed tile on the map stands for. Press O for all of them.`,
574	              })}
575	        />
576	      ) : (
577	        <>
578	          {intervening ? (
579	            <InterventionPanel
580	              world={world}
581	              // The open branch in the engine's own shape, so that a
582	              // claim the reader asks for is drafted and judged against
583	              // the map they are looking at rather than against the one
584	              // underneath it. Absent when the branch cannot be written
585	              // down in full, which is exactly when there is nothing
586	              // honest to send.
587	              {...(open?.wire === undefined ? {} : { branch: open.wire })}
588	              selection={selection}
589	              onEdit={edit}
590	              onClose={() => setIntervening(false)}
591	            />
592	          ) : null}
593	          <BranchPanel
594	            branches={shop.branches}
595	            openId={shop.openId}
596	            world={world}
597	            onOpen={(id) => setShop((was) => openBranch(was, id))}
598	            onFork={(label) => setShop((was) => forkBranch(was, label))}
599	            naming={naming}
600	            onNaming={setNaming}
601	          />
602	          {answer.at === "refused" ? <Refusal asking="this map" reasons={answer.reasons} /> : null}
603	          {open === undefined ? null : (
604	            <DeltaRail
605	              rows={rows}
606	              ranked={computed !== undefined}
607	              summary={computed === undefined ? NO_SUMMARY_YET : computed.change.summary}
608	            />
609	          )}
610	          <Inspector world={world} selection={selection} />
611	        </>
612	      )}
613	    </>
614	  );
615	
616	  return (
617	    <MapFrame
618	      title={base.title}
619	      onLeave={onLeave}
620	      onEveryKey={() => setOverlay("sheet")}
621	      where={
622	        open === undefined ? (
623	          <p className="map-bar__where">The map as it was written</p>
624	        ) : (
625	          <p className="map-bar__where">
626	            {/* A branch's hue rides on its name chip and its lane and nowhere
627	                else, and the chip always carries the branch's name — so which
628	                branch you are in is readable with no colour at all. */}
629	            <span className="map-bar__chip" data-hue={open.hue} aria-hidden="true" />
630	            {open.label}
631	            <span className="map-bar__side">
632	              {showing === "now" ? "with your edits" : "as it was written"}
633	            </span>
634	          </p>
635	        )
636	      }
637	      map={
638	        <MapCanvas
639	          world={world}
640	          selection={selection}
641	          onSelect={setSelection}
642	          focused={focused}
643	          onFocused={setFocused}
644	          heights={heights}
645	          mapKey={`${base.baseId}:${shop.openId ?? "as-written"}`}
646	          keys={keys}
647	          onStatus={setStatus}
648	          onOverflow={(column) => {
649	            setOnlyColumn(column);
650	            setDock("outline");
651	          }}
652	          arriving={arriving}
653	        />
654	      }
655	      overlay={
656	        <>
657	          {overlay === "palette" ? (
658	            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
659	          ) : null}
660	          {overlay === "sheet" ? (
661	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
662	          ) : null}
663	        </>
664	      }
665	      status={status}
666	      saying={announcement}
667	      panel={dock === "away" ? null : THE_PANEL}
668	      origin={
669	        <>
670	          <p className="map-origin__line">{world.origin}</p>
671	          {answer.at === "asking" ? (
672	            <p className="map-origin__line">{WHILE_ASKING.reason}</p>
673	          ) : null}
674	          {answer.at === "failed" ? (
675	            <p className="map-origin__line">
676	              {`The engine did not answer, so this is the map's shape with an absence wherever a ` +
677	                `likelihood would have moved. ${answer.reason}`}
678	            </p>
679	          ) : null}
680	          {insteadOfTheEngine === null ? null : (
681	            <p className="map-origin__line">{insteadOfTheEngine}</p>
682	          )}
683	          {(world.warnings ?? []).map((warning) => (
684	            <p className="map-origin__line" key={warning}>
685	              {warning}
686	            </p>
687	          ))}
688	        </>
689	      }
690	    />
691	  );
692	}
