/**
 * The screen a stored map is read and edited on.
 *
 * The map fills it, the panel beside it answers *why is this number what it
 * is*, and every edit a reader makes goes onto a branch of their own rather
 * than onto the map. Nothing here works a number out: the engine is asked for
 * the map with the branch folded on, and while it is being asked the slot says
 * so in words rather than showing a stale figure or a spinner.
 *
 * **The screen around the map is not here.** It is `MapFrame`, shared with the
 * map that builds itself: a bar with the way back, the stage, the panel in its
 * frame, one polite line said out loud and the origin strip at the foot. The
 * two screens were written twice and drifted the moment either was improved —
 * the panel's frame landed on one a round before the other, the error boundary
 * on one and never on the other.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { branchAnnouncement } from "../a11y/announcement";
import { outlineOf } from "../a11y/sentences";
import { RefusedBranch } from "../api/client";
import { MapCanvas } from "../graph/Canvas";
import { bothPaintings, type Engine, railRows } from "../graph/diff/branchWorld";
import { endings, NO_SUMMARY_YET } from "../graph/diff/endings";
import { roomFor } from "../graph/geometry";
import type { MapKeys } from "../keyboard/useMapKeys";
import {
  type Absence,
  appendEdit,
  type BranchView,
  type DiffView,
  type Edit,
  forkBranch,
  type Known,
  type LinkView,
  openBranch,
  type Ranged,
  type Reason,
  type Selection,
  type WorldSource,
  type WorldView,
  workshopOf,
} from "../world";
import { absence } from "../world/absence";
import { asOneSentence } from "../world/failures";
import { BranchPanel, InterventionPanel } from "./BranchPanel";
import { type Command, CommandPalette } from "./CommandPalette";
import { DeltaRail } from "./DeltaRail";
import { Inspector } from "./Inspector";
import { MapFrame } from "./MapFrame";
import { Outline } from "./Outline";
import { Refusal } from "./Refusal";
import { ShortcutsSheet } from "./ShortcutsSheet";

/** How long the wires take to arrive, column by column, before the map settles. */
const WAVE_SETTLES_AFTER = 1200;

/**
 * What stands where a likelihood would go while the engine is being asked for
 * one.
 *
 * The shared vocabulary has three ways of saying a number is not there, and
 * this is the third of them — *nothing has been computed* — because that is
 * exactly what is true while a question is in flight: the engine has been asked
 * and has not answered, so nothing has worked this number through the map
 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
 * on screen keeps its shape, the slots that will move say why they are empty,
 * and the line under the map says what has been asked for and where.
 */
const WHILE_ASKING: Absence = absence(
  "no_engine",
  "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
    "has not answered. Nothing has worked this number through the map yet.",
);

/**
 * What stands where a likelihood would go when the engine **refused** the
 * branch.
 *
 * Not "no engine yet": the engine is there and it answered — it said the branch
 * does not fit the map, and it said why. The words have to be true of that, and
 * the vocabulary's first three rows are all about a number nobody has worked out
 * rather than one that could not be. So there is a **fourth row** — *the engine
 * refused the branch these numbers would come from* → **not worked out** — and a
 * kind of its own to go with it, because "nothing has run yet" invites waiting
 * and "the engine turned this down" invites repairing what it turned down.
 */
const REFUSED: Absence = absence(
  "refused",
  "The engine would not work this map out from this branch: the branch does not fit the map. " +
    "Every reason is beside the map, and nothing on the map has changed.",
);

/**
 * What stands there when the engine could not be reached at all.
 *
 * **Not a refusal**, and the difference is the whole of why the two are separate
 * kinds. A refusal is an answer: the engine looked, said no, and said why, and
 * it will say the same thing until the branch is repaired. This is one attempt
 * that did not come back — the engine is there and it was asked — and it stops
 * being true the moment the reader asks again. So it takes the kind that is
 * never kept, and its reason says what to do about it.
 */
function unreachable(reason: string): Absence {
  return absence(
    "ask_failed",
    `${reason} Nothing on the map has changed; opening the branch again asks once more.`,
  );
}

/**
 * Everything the engine has said about the branch that is open, and whether it
 * has said it yet.
 */
type Answered =
  | { at: "asking" }
  | { at: "answered"; computed: { now: WorldView; change: DiffView } }
  | { at: "refused"; reasons: readonly Reason[] }
  | { at: "failed"; reason: string }
  | { at: "nothing-open" };

/**
 * Where the engine has got to, in the one shape the picture reads.
 *
 * Every state but *nothing is open* reserves the room an answer will take and
 * says why it is not there yet, so the map is the same size before and after the
 * answer lands and nothing on it jumps.
 */
function engineState(answer: Answered): Engine | undefined {
  switch (answer.at) {
    case "answered":
      return { at: "answered", now: answer.computed.now, change: answer.computed.change };
    case "asking":
      return { at: "waiting", absence: WHILE_ASKING };
    case "refused":
      return { at: "waiting", absence: REFUSED };
    case "failed":
      return { at: "waiting", absence: unreachable(answer.reason) };
    case "nothing-open":
      return undefined;
  }
}

/** Turn whatever the engine threw into either a list of reasons or one sentence. */
function asAnswer(reason: unknown): Answered {
  if (reason instanceof RefusedBranch) {
    return { at: "refused", reasons: reason.reasons };
  }
  return { at: "failed", reason: asOneSentence(reason) };
}

/**
 * The map, the panel beside it, and everything you can do to both.
 *
 * Three things live here rather than inside the map, because all three are about
 * the whole screen rather than about the picture: which branch is open, which of
 * the two worlds is painted, and what the keyboard is on.
 */
export function MapScreen({
  base,
  branches,
  source,
  insteadOfTheEngine,
  onLeave,
}: {
  base: WorldView;
  branches: readonly BranchView[];
  /** Where a branch's world, its difference and an arrow's number are asked for. */
  source: WorldSource;
  /** Why this map is the stored example rather than the engine's, or nothing. */
  insteadOfTheEngine: string | null;
  onLeave: () => void;
}) {
  const [shop, setShop] = useState(() => workshopOf(branches));
  const [showing, setShowing] = useState<"now" | "before">("now");
  const [selection, setSelection] = useState<Selection>(null);
  const [focused, setFocused] = useState<string | null>(null);
  const [dock, setDock] = useState<"panel" | "outline" | "away">("panel");
  const [onlyColumn, setOnlyColumn] = useState<{
    layer: number;
    claims: readonly string[];
  } | null>(null);
  const [overlay, setOverlay] = useState<"palette" | "sheet" | null>(null);
  const [intervening, setIntervening] = useState(false);
  const [naming, setNaming] = useState(false);
  const [status, setStatus] = useState(
    "Press ? for every key. j and k walk a column; h and l follow the wires.",
  );
  const [arriving, setArriving] = useState(true);
  const lastBranch = useRef<string | null>(null);

  const open = shop.branches.find((branch) => branch.id === shop.openId);

  // What the engine says about the branch that is open. It is asked again
  // whenever the branch changes — which is what makes the six buttons move
  // numbers: pressing one appends an edit, and the whole branch goes back.
  const [answer, setAnswer] = useState<Answered>({ at: "nothing-open" });
  useEffect(() => {
    if (open === undefined) {
      setAnswer({ at: "nothing-open" });
      return;
    }
    let stillWanted = true;
    setAnswer({ at: "asking" });
    Promise.all([
      source.readWorld({ baseId: base.baseId, branch: open }),
      source.readDiff({ baseId: base.baseId, branch: open }),
    ]).then(
      ([now, change]) => {
        if (stillWanted) {
          setAnswer({ at: "answered", computed: { now, change } });
        }
      },
      (failure: unknown) => {
        if (stillWanted) {
          setAnswer(asAnswer(failure));
        }
      },
    );
    return () => {
      // An answer to a question the reader has moved on from is thrown away
      // rather than drawn: a map that flickers back to an older branch because
      // a slower request finished last is a map nobody can trust.
      stillWanted = false;
    };
    // The branch itself is what this hangs on, and that is enough: appending an
    // edit hands back a new branch rather than changing the one that was there
    // — a branch is an audit trail and nothing rewrites one — so every press of
    // a button is a new question here, and nothing else is.
  }, [source, base.baseId, open]);

  // Held still between renders, because both paintings of the map hang on it: a
  // fresh object every render would lay the whole map out again on every keypress
  // for an answer that has not changed.
  const engine = useMemo(() => engineState(answer), [answer]);
  const computed = answer.at === "answered" ? answer.computed : undefined;

  // The numbers on the arrows, one at a time, kept once they arrive. Each one
  // costs a whole extra run of the map, so it is asked for when a reader selects
  // that arrow and never again for the same branch, seed and arrow.
  const [wireNumbers, setWireNumbers] = useState<ReadonlyMap<string, Known<Ranged>>>(new Map());
  // The last ask that did not come back, which is shown and never kept. A
  // failure is a fact about one attempt, not about the number: keeping it would
  // mean the reader who selects the arrow again after the server comes back is
  // told for the rest of the session that it cannot be worked out.
  const [wireFailed, setWireFailed] = useState<{ key: string; absence: Absence } | undefined>();
  const paintings = useMemo(
    () => (open === undefined ? null : bothPaintings(base, open, engine)),
    [base, open, engine],
  );

  const painted = paintings === null ? base : showing === "now" ? paintings.now : paintings.before;
  const seed = painted.seed;

  /**
   * The branch the map in front is drawn from — nothing, when the map in front
   * is the one as it was written.
   *
   * Flipping to "as it was written" puts the base map on screen, and an arrow's
   * number worked out under a branch is not a number about that map. This is the
   * branch every arrow number on this screen is asked for and named by, so the
   * question asked and the map drawn can never come apart.
   */
  const shownBranch = paintings === null || showing === "before" ? undefined : open;

  /**
   * What names one arrow's number: which branch, how far that branch has got,
   * which seed, which arrow.
   *
   * The edit count is in the name because a branch's `id` outlives its edits: an
   * edit appends to the branch and hands back a new one with the same id, so a
   * name without the count would hand a reader the number worked out before
   * their edit. Counting is enough to tell two branches apart because edits are
   * only ever appended — `appendEdit` is the one function that touches them, and
   * there is no undo (INV-workbench.49).
   */
  const wireKey = useCallback(
    (linkId: string) => {
      const whose =
        shownBranch === undefined ? "as-written" : `${shownBranch.id}@${shownBranch.edits.length}`;
      return `${whose}:${seed ?? "no-seed"}:${linkId}`;
    },
    [shownBranch, seed],
  );

  // The map as it is drawn: the world above, with any arrow number already
  // fetched put back on its own arrow.
  const world = useMemo((): WorldView => {
    if (wireNumbers.size === 0 && wireFailed === undefined) {
      return painted;
    }
    return {
      ...painted,
      links: painted.links.map((link): LinkView => {
        const key = wireKey(link.id);
        const asked = wireNumbers.get(key);
        if (asked !== undefined) {
          return { ...link, conditional: asked };
        }
        return wireFailed?.key === key
          ? { ...link, conditional: { absence: wireFailed.absence } }
          : link;
      }),
    };
  }, [painted, wireNumbers, wireFailed, wireKey]);

  /**
   * One box per claim, tall enough for whichever of the two paintings needs more
   * room — a claim grows badges when an edit touched it. Reserving the taller box
   * is what lets the union be laid out once and painted twice with nothing
   * moving.
   */
  const heights = useMemo(() => {
    if (paintings === null) {
      return undefined;
    }
    const reserved = new Map<string, number>();
    for (const side of [paintings.now, paintings.before]) {
      for (const claim of side.claims) {
        reserved.set(claim.id, Math.max(reserved.get(claim.id) ?? 0, roomFor(claim)));
      }
    }
    return reserved;
  }, [paintings]);

  // The endings the edit reaches. With the engine, its own ranked rows, in its
  // own order; without it, the reachable endings in map order, and the rail
  // says on its own face which of the two it is showing.
  const rows = useMemo(
    () =>
      computed !== undefined
        ? railRows(paintings?.now ?? base, computed.change)
        : paintings === null
          ? []
          : endings(paintings.now),
    [computed, paintings, base],
  );
  const outline = useMemo(() => outlineOf(world), [world]);

  // What the branch did, said out loud for a reader who is not looking at the
  // picture. It is said twice, because the two halves arrive at different
  // moments: the shape the instant the branch opens, and the counts when the
  // engine answers. The live region is polite, so the second line waits for a
  // pause rather than cutting across the first.
  const announcement = useMemo(
    () => (paintings === null ? "" : branchAnnouncement(paintings.now, computed?.change)),
    [paintings, computed],
  );

  // One arrow's own number, asked for when the reader selects that arrow and
  // kept afterwards. It is fetched here rather than by the wire because no
  // component in this product talks to the network, and because the answer
  // belongs to the whole screen: the panel and the plate on the wire read the
  // same one.
  useEffect(() => {
    if (selection?.kind !== "wire") {
      return;
    }
    const key = wireKey(selection.id);
    if (wireNumbers.has(key)) {
      return;
    }
    let stillWanted = true;
    source.readConditional({ baseId: base.baseId, branch: shownBranch, linkId: selection.id }).then(
      (slot) => {
        if (stillWanted) {
          setWireNumbers((was) => new Map(was).set(key, slot));
          setWireFailed((was) => (was?.key === key ? undefined : was));
        }
      },
      (failure: unknown) => {
        // Shown, and not filed with the answers. The engine is there and it was
        // asked — what is missing is this one attempt's reply, which is a
        // different thing from "nothing has worked this number out", and which
        // stops being true the moment the reader asks again.
        if (stillWanted) {
          setWireFailed({
            key,
            absence: absence(
              "ask_failed",
              `${asOneSentence(failure)} Select this arrow again to ask once more.`,
            ),
          });
        }
      },
    );
    return () => {
      stillWanted = false;
    };
  }, [selection, source, base.baseId, shownBranch, wireKey, wireNumbers]);

  // A branch has just been opened or made. Three things follow, in this order:
  // the map says out loud what the branch did, the wires arrive again in causal
  // order, and — because creating a claim moves focus to it — the keyboard lands
  // on the claim the branch added, so the view frames the thing you just made
  // rather than leaving you to hunt for it.
  useEffect(() => {
    if (shop.openId === lastBranch.current) {
      return;
    }
    lastBranch.current = shop.openId;
    setShowing("now");
    setArriving(true);
    if (paintings === null) {
      return;
    }
    const arrived = paintings.now.claims.find((claim) => claim.diff === "added");
    if (arrived !== undefined) {
      setFocused(arrived.id);
      setSelection({ kind: "claim", id: arrived.id });
      setStatus(`your edit added this claim · ${arrived.claim}`);
    }
  }, [shop.openId, paintings]);

  // The wave settles on its own clock, and on nothing else.
  //
  // **It has to be its own effect.** The one above runs again whenever the
  // picture changes — and the picture changes when the engine answers, which is
  // a moment or two after a branch is opened. A timer started up there would be
  // cleared by that second run and never started again, and the map would stay
  // mid-arrival for ever, which is to say invisible.
  useEffect(() => {
    if (!arriving) {
      return;
    }
    const settles = window.setTimeout(() => setArriving(false), WAVE_SETTLES_AFTER);
    return () => window.clearTimeout(settles);
  }, [arriving]);

  const edit = useCallback((made: Edit) => {
    setShop((was) =>
      appendEdit(was.openId === null ? forkBranch(was, "Your own branch") : was, made),
    );
  }, []);

  const keys: MapKeys = useMemo(
    () => ({
      intervene: () => {
        setDock("panel");
        setIntervening(true);
      },
      branch: () => {
        setDock("panel");
        setNaming(true);
      },
      flipWorlds: () => {
        if (paintings === null) {
          setStatus("there is nothing to flip to — no branch is open");
          return;
        }
        setShowing((was) => {
          const next = was === "now" ? "before" : "now";
          setStatus(
            next === "now"
              ? "the map with your edits"
              : "the map as it was written, with what your branch adds drawn faint",
          );
          return next;
        });
      },
      outline: () =>
        setDock((was) => {
          setOnlyColumn(null);
          return was === "outline" ? "panel" : "outline";
        }),
      panel: () => setDock((was) => (was === "away" ? "panel" : "away")),
      palette: () => setOverlay("palette"),
    }),
    [paintings],
  );

  // ⌘K, ? and Escape work wherever you are on the screen, not only on the map,
  // because two of them are how you find out what the others do.
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      const target = event.target as HTMLElement | null;
      const typing =
        target?.tagName === "INPUT" ||
        target?.tagName === "TEXTAREA" ||
        target?.isContentEditable === true;
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setOverlay((was) => (was === "palette" ? null : "palette"));
        return;
      }
      if (event.key === "Escape") {
        setOverlay(null);
        setIntervening(false);
        setNaming(false);
        return;
      }
      if (event.key === "?" && !typing) {
        event.preventDefault();
        setOverlay((was) => (was === "sheet" ? null : "sheet"));
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const commands: Command[] = useMemo(() => {
    const made: Command[] = [
      {
        name: "The map as it was written",
        does: "Close the branch. Also the first row of the branch panel.",
        run: () => setShop((was) => openBranch(was, null)),
      },
      ...shop.branches.map((branch) => ({
        name: `Open the branch: ${branch.label}`,
        does: `${branch.edits.length} edits. Also a row in the branch panel.`,
        run: () => setShop((was) => openBranch(was, branch.id)),
      })),
      {
        name: "Flip between the two maps",
        does: "The same as pressing Space on the map. A hard switch, never a fade.",
        run: keys.flipWorlds,
      },
      {
        name: "Change this claim",
        does: "The six things you can do to it. The same as pressing E on the map.",
        run: keys.intervene,
      },
      {
        name: "Start a branch",
        does: "The same as pressing B on the map, and as the button in the branch panel.",
        run: keys.branch,
      },
      {
        name: "Read the map as a list",
        does: "The same as pressing O. Every claim, one sentence each.",
        run: () => {
          setOnlyColumn(null);
          setDock("outline");
        },
      },
      {
        name: "Show or hide the panel beside the map",
        does: "The same as pressing P, when you want the whole width for the map.",
        run: keys.panel,
      },
      {
        name: "Every key, on one sheet",
        does: "The same as pressing the question mark.",
        run: () => setOverlay("sheet"),
      },
      {
        name: "Back to the launchpad",
        does: "The same as the link at the top left.",
        run: onLeave,
      },
    ];
    return made;
  }, [shop.branches, keys, onLeave]);

  const pick = useCallback((id: string) => {
    setFocused(id);
    setSelection({ kind: "claim", id });
  }, []);

  const THE_PANEL = (
    <>
      {dock === "outline" ? (
        <Outline
          items={outline}
          onPick={pick}
          focused={focused}
          {...(onlyColumn === null
            ? {}
            : {
                only: new Set(onlyColumn.claims),
                filter:
                  `Only the claims in column ${onlyColumn.layer}, which is what the ` +
                  `collapsed tile on the map stands for. Press O for all of them.`,
              })}
        />
      ) : (
        <>
          {intervening ? (
            <InterventionPanel
              world={world}
              // The open branch in the engine's own shape, so that a
              // claim the reader asks for is drafted and judged against
              // the map they are looking at rather than against the one
              // underneath it. Absent when the branch cannot be written
              // down in full, which is exactly when there is nothing
              // honest to send.
              {...(open?.wire === undefined ? {} : { branch: open.wire })}
              selection={selection}
              onEdit={edit}
              onClose={() => setIntervening(false)}
            />
          ) : null}
          <BranchPanel
            branches={shop.branches}
            openId={shop.openId}
            world={world}
            onOpen={(id) => setShop((was) => openBranch(was, id))}
            onFork={(label) => setShop((was) => forkBranch(was, label))}
            naming={naming}
            onNaming={setNaming}
          />
          {answer.at === "refused" ? <Refusal asking="this map" reasons={answer.reasons} /> : null}
          {open === undefined ? null : (
            <DeltaRail
              rows={rows}
              ranked={computed !== undefined}
              summary={computed === undefined ? NO_SUMMARY_YET : computed.change.summary}
            />
          )}
          <Inspector world={world} selection={selection} />
        </>
      )}
    </>
  );

  return (
    <MapFrame
      title={base.title}
      onLeave={onLeave}
      onEveryKey={() => setOverlay("sheet")}
      where={
        open === undefined ? (
          <p className="map-bar__where">The map as it was written</p>
        ) : (
          <p className="map-bar__where">
            {/* A branch's hue rides on its name chip and its lane and nowhere
                else, and the chip always carries the branch's name — so which
                branch you are in is readable with no colour at all. */}
            <span className="map-bar__chip" data-hue={open.hue} aria-hidden="true" />
            {open.label}
            <span className="map-bar__side">
              {showing === "now" ? "with your edits" : "as it was written"}
            </span>
          </p>
        )
      }
      map={
        <MapCanvas
          world={world}
          selection={selection}
          onSelect={setSelection}
          focused={focused}
          onFocused={setFocused}
          heights={heights}
          mapKey={`${base.baseId}:${shop.openId ?? "as-written"}`}
          keys={keys}
          onStatus={setStatus}
          onOverflow={(column) => {
            setOnlyColumn(column);
            setDock("outline");
          }}
          arriving={arriving}
        />
      }
      overlay={
        <>
          {overlay === "palette" ? (
            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
          ) : null}
          {overlay === "sheet" ? (
            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
          ) : null}
        </>
      }
      status={status}
      saying={announcement}
      panel={dock === "away" ? null : THE_PANEL}
      origin={
        <>
          <p className="map-origin__line">{world.origin}</p>
          {answer.at === "asking" ? (
            <p className="map-origin__line">{WHILE_ASKING.reason}</p>
          ) : null}
          {answer.at === "failed" ? (
            <p className="map-origin__line">
              {`The engine did not answer, so this is the map's shape with an absence wherever a ` +
                `likelihood would have moved. ${answer.reason}`}
            </p>
          ) : null}
          {insteadOfTheEngine === null ? null : (
            <p className="map-origin__line">{insteadOfTheEngine}</p>
          )}
          {(world.warnings ?? []).map((warning) => (
            <p className="map-origin__line" key={warning}>
              {warning}
            </p>
          ))}
        </>
      }
    />
  );
}

/**
 * The rail beside the map: the endings your edit can reach.
 *
 * An **ending** is where an argument turns into a position — a claim that names
 * something you could trade, or one that names why there is nothing to trade.
 * The rail lists the ones this edit can reach and, beside each, three things:
 * how far its number moved, **how firm** that number is, and whether it went the
 * **same direction** whatever numbers the map started from.
 *
 * **The rail ranks nothing.** When the engine has ordered these rows — largest
 * move along the best-backed route first — the rail draws them in that order and
 * says so. When nothing has, it lists them in the order the map stores them and
 * says *that*, because map order is visibly arbitrary while an invented ranking
 * looks like an answer, and a ranking is the one thing the rail exists to tell
 * you.
 *
 * **An ending that did not move still gets a row.** The engine lists the ones
 * that moved; an ending missing from that list could mean either "it held still"
 * or "it is not on this map", and silence cannot be told from absence. So the
 * unmoved ones follow the ranked ones, reading *no change*, never mixed in among
 * them.
 *
 * The two columns are never folded into any ordering. They answer different
 * questions and a trader weighs them separately; folding the width into a rank
 * would sink exactly the claims that most deserve a second look.
 */

import { useId, useState } from "react";
import { toDay } from "../graph/diff/days";
import type { DeltaRow, Known } from "../world";
import { toMovement, toShare, toSize } from "./BeliefChip";
import "./deltaRail.css";

/** What the rail needs to draw itself. */
export interface DeltaRailProps {
  /** The endings this edit can reach, in whatever order they arrived in. */
  readonly rows: readonly DeltaRow[];
  /**
   * Whether something has put these rows in an order that means something.
   *
   * True once the engine has ranked them. False before that, and the rail says
   * so out loud rather than letting map order be mistaken for a ranking.
   */
  readonly ranked: boolean;
  /** The one line saying what this edit did to the trades, or the reason there is none. */
  readonly summary: Known<string>;
}

/** What each kind of ending is, in a word. */
const KIND_WORDS: Record<string, string> = {
  market: "tradeable",
  not_tradeable: "not tradeable",
  event: "event",
  hypothesis: "hypothesis",
};

/**
 * One cell: the number, or the words standing where it would have been.
 *
 * A cell with no number is a button, because the reason it has no number is a
 * sentence and there is no room for a sentence in a column this narrow. Pressing
 * it prints the sentence under the rail; its accessible name carries the same
 * sentence, so a reader who never sees the rail gets it without pressing
 * anything.
 */
function Cell({
  value,
  onReason,
}: {
  value: Known<string>;
  onReason: (reason: string | null) => void;
}) {
  if (value.reading !== undefined) {
    return <span className="delta-rail__value">{value.reading}</span>;
  }
  const { words, reason } = value.absence;
  return (
    <button
      className="delta-rail__value delta-rail__value--absent"
      type="button"
      aria-label={`${words}. ${reason}`}
      onClick={() => onReason(reason)}
      onFocus={() => onReason(reason)}
      onMouseEnter={() => onReason(reason)}
    >
      {words}
    </button>
  );
}

/**
 * The change itself, as one cell reads it: `.50 ▼ .42`, and the day the two
 * worlds were furthest apart.
 *
 * A row is read on the **day of largest divergence** rather than on the claim's
 * own judging day, because a change that shows up for a fortnight and then
 * unwinds is the thing a trader acts on — so the row names that day.
 */
function changeOf(row: DeltaRow): Known<string> {
  const move = row.move.reading;
  if (move === undefined) {
    return { absence: row.move.absence };
  }
  return { reading: toMovement(move.from, move.to, move.by, move.way) };
}

/**
 * How firm the new number is: the width of its own range.
 *
 * A width is a **size**, not a likelihood: it is how far apart the two ends of a
 * band sit. So it takes no certainty guard — a band four thousandths wide is a
 * remarkably firm number and the reader wants to see it, where `<.01` would say
 * only that it is small.
 */
function firmnessOf(row: DeltaRow): Known<string> {
  return row.rangeWidth.reading === undefined
    ? { absence: row.rangeWidth.absence }
    : { reading: toSize(row.rangeWidth.reading) };
}

/** The share of versions of the map that moved the same way, as a whole percentage. */
function sameDirectionOf(row: DeltaRow): Known<string> {
  return row.agreement.reading === undefined
    ? { absence: row.agreement.absence }
    : { reading: toShare(row.agreement.reading) };
}

/** The rail beside the map. */
export function DeltaRail({ rows, ranked, summary }: DeltaRailProps) {
  const [reason, setReason] = useState<string | null>(null);
  const headingId = useId();

  return (
    <section className="delta-rail" aria-labelledby={headingId}>
      <h2 className="delta-rail__heading" id={headingId}>
        Where this edit ends up
      </h2>

      {/* The one line saying what the edit did to the trades. The engine writes
          it from a fixed template with its own numbers in the blanks; before it
          has, the slot says why there is none. */}
      <p className="delta-rail__summary">
        {summary.reading ?? summary.absence.words}
        {summary.reading === undefined ? (
          <span className="delta-rail__summary-reason">{summary.absence.reason}</span>
        ) : null}
      </p>

      {rows.length === 0 ? (
        <p className="delta-rail__empty">
          No ending on this map is reachable from your edits yet. Make one — press E on a claim —
          and the endings it can reach are listed here.
        </p>
      ) : (
        <>
          <p className="delta-rail__order">
            {ranked
              ? "In the order the engine put them in: the size of the move times the weakest arrow on the best-backed route behind it. Endings that did not move follow, and are not ranked."
              : "In map order. Nothing has ranked these, because nothing has worked out a number to rank them by."}
          </p>

          <div className="delta-rail__table">
            <div className="delta-rail__labels" aria-hidden="true">
              <span>change</span>
              <span>how firm</span>
              <span>same direction</span>
            </div>
            <ul className="delta-rail__rows">
              {rows.map((row, place) => (
                <li
                  className="delta-rail__row"
                  key={row.claimId}
                  data-moved={row.noChange === true ? "no" : "yes"}
                >
                  <p className="delta-rail__label">
                    {/* Where this ending sits in the engine's own order, which is
                        what the rail is for. It was the claim's identifier, and on
                        a generated map that is twenty-six characters nobody reads
                        (`world/naming.ts`). */}
                    <span className="delta-rail__id">{place + 1}</span>
                    {row.label}
                    <span className="delta-rail__kind">{KIND_WORDS[row.kind] ?? row.kind}</span>
                    {row.move.reading === undefined ? null : (
                      <span className="delta-rail__day">
                        {`${row.move.reading.way} · largest on ${toDay(row.move.reading.largestOn)}`}
                      </span>
                    )}
                  </p>
                  <div className="delta-rail__values">
                    <Cell value={changeOf(row)} onReason={setReason} />
                    <Cell value={firmnessOf(row)} onReason={setReason} />
                    <Cell value={sameDirectionOf(row)} onReason={setReason} />
                  </div>
                </li>
              ))}
            </ul>
          </div>

          <p className="delta-rail__reason">
            {reason ??
              "Every reading above is the engine's own, in the engine's own order. Reach one with " +
                "the keyboard, or point at it, and whatever it has to say is printed here."}
          </p>
        </>
      )}
    </section>
  );
}

/**
 * The first screen: what you can start from, and the two ways in.
 *
 * No illustration and no empty box staring back. The two doors are named and
 * explained in a line each, the stored example opens a map that is already drawn,
 * and the four sentences from the brief each build one in front of you.
 *
 * **A card has three states and no others.** It runs live, it runs from a
 * recording, or it reads *not yet live* — and that last one now means one thing
 * only: **no model key and no recording**, an example nobody has recorded yet,
 * which is an honest state rather than the catch-all it used to be.
 *
 * **With no key, the four run from recordings through the same route, the same
 * eight events and the same canvas.** The sentence that says so is record 0012's,
 * word for word, and the day in it is read from the server's own readiness answer
 * — never from a file name, never from a build date, never from the browser's own
 * clock. Where the four were not all recorded on one day, the shared sentence
 * names the **oldest** day in the set and each card carries its own, so the
 * sentence is never more current than the oldest thing it describes.
 *
 * **This screen reads what can be replayed and whether a key is configured, and
 * ignores whether the server called itself ready.** A program with no key but
 * four recordings can do everything a reviewer came to see, and a card greyed out
 * because the whole server called itself not ready would be the most misleading
 * screen in the product.
 */

import type { FixtureSummary, Readiness } from "../api/client";
import { countInWords } from "../world/naming";
import type { Asked } from "./InputBar";
import { InputBar } from "./InputBar";
import "./launchpad.css";

/** One of the two ways into the tool. */
interface Door {
  readonly name: string;
  readonly line: string;
}

/**
 * The two doors, from the requirements: start from an event and follow it out,
 * or name where you think it ends and ask whether the chain really gets there.
 */
const DOORS: readonly Door[] = [
  {
    name: "Explore",
    line: "Start from an event and see what it would cause, out to the things you could trade.",
  },
  {
    name: "Verify",
    line: "Name where you think it ends, and see whether a chain really gets there — or that none does.",
  },
];

/** One of the four sentences from the brief, and which recording answers to it. */
export interface StartingSentence {
  /**
   * Which stored example this is.
   *
   * It is the name the readiness answer uses for a recording, so that a card can
   * say whether there is one to play. It is **not** a file name and it never
   * reaches a request: what a card sends is its sentence, exactly as a reader
   * would type it, which is what makes the replayed path and the live path send
   * byte-identical requests.
   */
  readonly example: string;
  /** The sentence, as a person would actually type it. */
  readonly sentence: string;
}

/** The four examples from the brief, in the order the brief lists them. */
export const STARTING_SENTENCES: readonly StartingSentence[] = [
  { example: "hormuz", sentence: "The Strait of Hormuz is going to open next week." },
  {
    example: "midterms",
    sentence: "Republicans win the House but Democrats take the Senate during the midterms.",
  },
  {
    example: "export-controls",
    sentence: "Models more capable than Fable get export restricted by the United States.",
  },
  { example: "photonics", sentence: "Photonic chips get adopted faster than expected." },
];

/**
 * Record 0012's sentence, word for word, with the day the readiness answer gave.
 *
 * **It is printed only when it is true**: when all four of the sentences below
 * can be played and all four were recorded on the same day. Anything else and it
 * would be a screen claiming something a reader can see is false — three cards
 * reading *not yet live* under a line saying these four run from recordings — and
 * the one screen this product cannot afford to be caught out on is the one that
 * exists to say what this copy can honestly do.
 *
 * @param day The day the recordings were made.
 */
export function keylessSentence(day: string): string {
  return `No model key configured — these four run from recordings made on ${day}.`;
}

/**
 * What this copy can play, in one or two sentences, and always true.
 *
 * Four shapes, and the first is record 0012's own words. The others say the same
 * kind of thing in the same voice: how many of the four can be played, how many
 * cannot, and the day — the **oldest** day, where there is more than one, so the
 * sentence is never more current than the oldest thing it describes.
 *
 * @param days The day each playable example was recorded on, in any order.
 * @param outOf How many sentences the screen offers altogether.
 */
export function whatThisCopyCanPlay(days: readonly string[], outOf: number): string | null {
  if (days.length === 0) {
    return null;
  }
  const sorted = [...days].sort();
  const oldest = sorted[0] as string;
  const allOfThem = days.length === outOf;
  const oneDay = sorted[sorted.length - 1] === oldest;

  if (allOfThem && oneDay) {
    return keylessSentence(oldest);
  }
  if (allOfThem) {
    return (
      `No model key configured — these ${countInWords(outOf)} run from recordings, the oldest ` +
      `made on ${oldest}.`
    );
  }
  const rest = outOf - days.length;
  const canPlay = days.length === 1 ? "runs" : "run";
  const cannot = rest === 1 ? "has" : "have";
  const theRest = rest === 1 ? "the other one" : `the other ${countInWords(rest)}`;
  const when = oneDay ? `made on ${oldest}` : `the oldest made on ${oldest}`;
  return (
    `No model key configured — ${countInWords(days.length)} of these ${countInWords(outOf)} ` +
    `${canPlay} from recordings, ${when}; ${theRest} ${cannot} nothing recorded yet.`
  );
}

/** What each card can do, which is one of exactly three things. */
type CardState = "live" | "replay" | "not-yet";

/** What the launchpad needs to draw itself. */
export interface LaunchpadProps {
  /**
   * The stored examples the server ships with, or null while the answer is still
   * on its way.
   */
  readonly examples: readonly FixtureSummary[] | null;
  /** Why the list could not be read, if it could not be. */
  readonly failure: string | null;
  /**
   * What the server said about itself: whether a key is configured, and what it
   * can play back. Null while that answer is still on its way.
   */
  readonly readiness: Readiness | null;
  /** Open a stored example's map, already drawn. */
  readonly onOpen: (id: string) => void;
  /** Build a map from a sentence. */
  readonly onBuild: (asked: Asked) => void;
}

/** The first screen. */
export function Launchpad({ examples, failure, readiness, onOpen, onBuild }: LaunchpadProps) {
  // The two facts this screen reads, and the one it deliberately does not.
  const hasKey = readiness?.model_key_present === true;
  const recorded = new Map(
    (readiness?.replayable ?? []).map((one) => [one.example, one.recording_date]),
  );
  // The day each of the four sentences was recorded on, for the ones that were.
  // Read off the cards rather than off the whole answer, so a recording of
  // something this screen does not offer cannot make its sentence wrong.
  const playable = STARTING_SENTENCES.map((one) => recorded.get(one.example)).filter(
    (day): day is string => day !== undefined,
  );
  const canPlay = whatThisCopyCanPlay(playable, STARTING_SENTENCES.length);
  const stateOf = (example: string): CardState =>
    hasKey ? "live" : recorded.has(example) ? "replay" : "not-yet";

  return (
    <div className="launchpad">
      <section className="launchpad__doors" aria-labelledby="doors-heading">
        <h2 className="section-heading" id="doors-heading">
          Two ways in
        </h2>
        <ul className="doors">
          {DOORS.map((door) => (
            <li className="door" key={door.name}>
              <span className="door__name">{door.name}</span>
              <span className="door__line">{door.line}</span>
            </li>
          ))}
        </ul>
      </section>

      <section className="launchpad__drawn" aria-labelledby="examples-heading">
        <h2 className="section-heading" id="examples-heading">
          A map that is already drawn
        </h2>
        <ul className="examples">
          {examples === null ? (
            <li className="example example--waiting">
              <span className="example__claim">
                {failure ?? "Asking the server which examples it ships with."}
              </span>
              {failure === null ? <span className="placeholder" aria-hidden="true" /> : null}
            </li>
          ) : (
            examples.map((example) => (
              <li key={example.id}>
                <button
                  className="example example--live"
                  type="button"
                  onClick={() => onOpen(example.id)}
                >
                  <span className="example__claim">{example.title}</span>
                  <span className="example__line">{example.one_line}</span>
                  <span className="example__action">Open the map</span>
                </button>
              </li>
            ))
          )}
        </ul>
      </section>

      <section className="launchpad__build" aria-labelledby="build-heading">
        <h2 className="section-heading" id="build-heading">
          Or watch one build itself
        </h2>
        <ul className="examples">
          {STARTING_SENTENCES.map((one) => {
            const state = stateOf(one.example);
            const day = recorded.get(one.example);
            return (
              <li key={one.example}>
                {state === "not-yet" ? (
                  <div className="example example--waiting" data-state="not-yet">
                    <span className="example__claim">{one.sentence}</span>
                    <span className="example__line">
                      Would be turned into a map of what it causes, ending in trades.
                    </span>
                    <span className="example__action example__action--waiting">
                      <span className="example__badge">not yet live</span>
                      no model key, and nothing recorded for this one
                    </span>
                  </div>
                ) : (
                  <button
                    className="example example--live"
                    type="button"
                    data-state={state}
                    onClick={() =>
                      onBuild({ hypothesis: one.sentence, target: null, belief: null })
                    }
                  >
                    <span className="example__claim">{one.sentence}</span>
                    <span className="example__line">
                      {state === "replay"
                        ? "Plays the recording of this run back, claim by claim, through the same route and the same canvas."
                        : "Builds a map of what it would cause, claim by claim, ending in trades."}
                    </span>
                    {/* Not **Build the map**: that is the one button on the
                        input bar, and a word that names two controls names
                        neither. A card is a sentence somebody already typed. */}
                    <span className="example__action">
                      {state === "replay" ? (
                        <>
                          <span className="example__badge">replay</span>
                          {day === undefined ? "Watch it build" : `recorded ${day}`}
                        </>
                      ) : (
                        "Watch it build"
                      )}
                    </span>
                  </button>
                )}
              </li>
            );
          })}
        </ul>

        {/* Record 0012's sentence, word for word, under the four cards — and
            again under the field below, which is disabled with it. */}
        {canPlay === null || hasKey ? null : <p className="launchpad__keyless">{canPlay}</p>}
        {/* What *not yet live* means, said once in full rather than three times
            over: each card carries the short form, and this is the whole of it.
            It is the honest state now, not a catch-all — a key would run it, and
            a recording would play it, and this copy has neither. */}
        {hasKey || STARTING_SENTENCES.every((one) => recorded.has(one.example)) ? null : (
          <p className="launchpad__keyless launchpad__keyless--quiet">
            A card reads <b>not yet live</b> when this copy has no model key and nobody has recorded
            that example, so there is nothing it could honestly show you.
          </p>
        )}
        {/* **A recording that would not play is named, in the server's own
            sentence.** A reviewer who put a file in the recordings folder and
            then counts three cards where they expected four is owed the reason
            rather than left to wonder whether they put it in the wrong place —
            and a recording is a committed file that outlives the code that
            wrote it, so meeting one this engine cannot read is ordinary. It is
            quiet, under the cards, because it is about the copy rather than
            about the maps: the cards that do play are unaffected, which is the
            other half of the same rule. */}
        {(readiness?.unreadable ?? []).map((sentence) => (
          <p className="launchpad__keyless launchpad__keyless--quiet" key={sentence}>
            {sentence}
          </p>
        ))}
      </section>

      {/* A sentence of the reader's own. It is a section of its own rather than
          a footnote under the four cards, because typing your own event is the
          way in this product is for and the four are the shortcut. */}
      <section className="launchpad__yours" aria-labelledby="yours-heading">
        <h2 className="section-heading" id="yours-heading">
          Or start from a sentence of your own
        </h2>
        <InputBar
          disabledBecause={
            hasKey
              ? null
              : canPlay === null
                ? "This copy has no model key and no recordings, so a sentence of your own cannot be turned into a map."
                : `${canPlay} A sentence of your own needs the model, and there is no recording of one.`
          }
          onBuild={onBuild}
        />
      </section>
    </div>
  );
}

