220:.dock {
262:.dock-frame {
270:.dock-frame::before,
271:.dock-frame::after {
282:.dock-frame::before {
286:.dock-frame::after {
292:.dock-frame:not([data-more-above="yes"])::before,
293:.dock-frame:not([data-more-below="yes"])::after {
338:.page--map .dock > * {
=== outline.css 40-90 ===

.outline__item[data-level="2"] {
  padding-left: var(--space-2);
}

.outline__item[data-level="3"] {
  padding-left: var(--space-4);
}

.outline__item[data-level="4"] {
  padding-left: var(--space-5);
}

.outline__item[data-level="5"] {
  padding-left: var(--space-6);
}

.outline__line {
  display: grid;
  grid-template-columns: 2.4em 1fr;
  column-gap: var(--space-1);
  width: 100%;
  margin: 0;
  padding: var(--space-hair) var(--space-1);
  border: 1px solid transparent;
  border-left: 1px solid var(--hairline);
  border-radius: 0 var(--radius) var(--radius) 0;
  background: none;
  font-family: var(--font-interface);
  font-size: var(--text-sm);
  line-height: 1.45;
  color: var(--text);
  text-align: left;
  text-wrap: pretty;
  cursor: pointer;
}

.outline__line:hover {
  border-color: var(--hairline);
  background: var(--surface);
}

.outline__item[aria-selected="true"] .outline__line {
  border-color: var(--accent);
}

.outline__id {
  font-family: var(--font-mono);
  font-weight: var(--weight-semibold);
  color: var(--text-muted);
}

