738	
739	  // **Before the answer.** The line is already there, saying what it is waiting
740	  // for, and the tile is the size it will keep.
741	  const movement = strait.locator('.tile__badge[data-badge="movement"]');
742	  await expect(movement).toBeVisible();
743	  // Word for word the sentence the engine's own absence carries while it is
744	  // being asked — not merely a sentence with "engine" in it, which the answer
745	  // has too. This is what makes the two moments below two moments.
746	  await expect(movement.locator(".tile__badge-words")).toHaveText("no engine yet");
747	  await expect(movement).toHaveAttribute(
748	    "title",
749	    /has been asked at \/api\/worlds .* and has not answered/,
750	  );
751	  const tile = strait.locator(".tile");
752	  const whileWaiting = await tile.evaluate((el) => (el as HTMLElement).offsetHeight);
753	
754	  holding = false;
755	
756	  // **After the answer.** The line reads the engine's own two numbers, and the
757	  // tile is the same size it was: nothing grew when the answer landed.
758	  await expect(movement).toHaveAttribute("title", /\.\d+.*\.\d+/);
759	  await expect(strait).not.toContainText("no engine yet");
760	  const said = (await movement.getAttribute("title")) ?? "";
761	  const readings = [...said.matchAll(/(?<![\d.])\.\d+/g)].map((one) => one[0]);
762	  expect(readings.length).toBeGreaterThanOrEqual(2);
763	  // The two are the engine's readings of this claim, and they are not the same
764	  // number — which is the whole point: the source moved.
765	  expect(readings[0]).not.toBe(readings[1]);
766	
767	  await expect
768	    .poll(() => tile.evaluate((el) => (el as HTMLElement).offsetHeight))
769	    .toBe(whileWaiting);
770	});
771	
772	/**
773	 * The map keeps its arrows when the browser drops the tiles' size notifications.
774	 *
775	 * **This is the browser's own failure mode, made total and deterministic.** A
776	 * `ResizeObserver` is how the drawing library learns how big a thing is, and
777	 * when too many observations fall due in one frame the browser abandons the
778	 * rest — *"a ResizeObserver loop completed with undelivered notifications"* —
779	 * and an abandoned one is never delivered. #37 met that as tiles that never
780	 * appeared, and fixed it by telling the library each tile's box outright.
781	 *
782	 * **A wire needs more than a box.** It is drawn between two ports — the sockets
783	 * on a tile's edges — and where a port sits inside a tile used to be measured
784	 * through the very same notification. So with the tiles' notifications dropped
785	 * the map drew every claim, in its place, visible — and not one arrow. A causal
786	 * map is its arrows: what is left is the wrong picture of the argument, and a
787	 * silent one.
788	 *
789	 * **It is per tile, which is why it shows up as one missing arrow rather than
790	 * an empty map.** Measured, dropping one tile's notifications and keeping every
791	 * other: deafen the insurance premium and the two arrows that touch it go, and
792	 * only those; deafen the strait and its three go. An arrow is not drawn when
793	 * *either* end was never measured. That is the shape the end-to-end suite met
794	 * in the wild — `H->C` absent from the glass, everything else in place — about
795	 * once in two hundred runs at six workers on a loaded machine.
796	 *
797	 * **Why it passes now, and why nothing is retried to make it pass.** Every
798	 * tile hands the drawing library its box and its four ports outright, worked
799	 * out by `graph/ports.ts` and written onto the tile in the same numbers, so
800	 * both ends of every arrow are known before the page has been measured once.
801	 * With the tiles deaf, this map is drawn exactly as it is drawn with them
802	 * hearing — which is the strongest form of the claim, and the reason nothing
803	 * here waits or asks again.
804	 *
805	 * The shim below drops only the tiles' notifications and lets the glass's own
806	 * through, because the library needs that one to draw anything at all.
807	 */
808	test("test_the_arrows_are_drawn_when_the_browser_drops_a_size_notification", async ({ page }) => {
809	  await page.addInitScript(() => {
810	    const Real = window.ResizeObserver;
811	    // Written as a plain function rather than a class on purpose: a private
812	    // field here is compiled to a helper the page has never heard of.
813	    function DropsTilesNotifications(given: ResizeObserverCallback) {
814	      const real = new Real((entries, observer) => {
815	        const kept = entries.filter((one) => one.target.closest(".react-flow__node") === null);
816	        if (kept.length > 0) {
817	          given(kept, observer);
818	        }
819	      });
820	      return {
821	        observe: (target: Element, options?: ResizeObserverOptions) =>
822	          real.observe(target, options),
823	        unobserve: (target: Element) => real.unobserve(target),
824	        disconnect: () => real.disconnect(),
825	      };
826	    }
827	    window.ResizeObserver = DropsTilesNotifications as unknown as typeof ResizeObserver;
828	  });
829	
830	  await page.goto("/");
831	  await page
832	    .getByRole("button", { name: /Strait of Hormuz/ })
833	    .first()
834	    .click();
835	  await waitForTheLayout(page, 7);
836	
837	  // Every claim, visible — which is #37's half of this, and still holding.
838	  await expect
839	    .poll(() =>
840	      page
841	        .locator(".react-flow__node")
842	        .evaluateAll(
843	          (tiles) => tiles.filter((tile) => getComputedStyle(tile).visibility === "hidden").length,
844	        ),
845	    )
846	    .toBe(0);
847	
848	  // And every arrow, by name — the same check the stored example gets with the
849	  // browser behaving, so that this test says *nothing changes* rather than
850	  // merely *something was drawn*.
851	  await everyArrowIsDrawn(page);
852	});
853

