1	/**
2	 * The six buttons, the badges they earn, and the words that may not appear.
3	 *
4	 * The six operations keep their code names in the code, in the wire format and
5	 * in the spec — `do`, `observe`, `insert`, `retune`, `refine`, `believe` — and
6	 * **not one of them ever reaches the screen.** The reader sees the button they
7	 * pressed and the badge it earned, copied word for word from the shared
8	 * vocabulary. This file is what stops the two drifting apart.
9	 */
10	
11	import { fireEvent, render, screen } from "@testing-library/react";
12	import { describe, expect, it, vi } from "vitest";
13	import { aClaim, aWire, aWorld } from "../../test/aMap";
