28	/** The six code names, none of which may appear on screen. */
29	const CODE_NAMES = ["observe", "insert", "retune", "refine", "believe"];
30	
31	/** A world with one claim and one arrow, enough for the panel to read back. */
32	const WORLD = aWorld({
33	  claims: [
34	    aClaim({ id: "H", kind: "hypothesis", claim: "The Strait of Hormuz reopens." }),
35	    aClaim({ id: "B", claim: "Brent crude settles below $68 for five sessions." }),
36	  ],
37	  links: [aWire({ id: "H->B", source: "H", target: "B" })],
38	});
39	
40	/** The stored example's own branch: three edits, in the order they were made. */
41	const STRIKE: BranchView = {
42	  id: "br_hormuz_then_strike",
43	  label: "Hormuz opens, then Iran is struck",
44	  hue: "violet",
45	  edits: [
46	    { op: "do", target: "H", value: true, at: "2026-10-01" },
47	    {
48	      op: "insert",
49	      claimId: "S",
