64	
65	describe("the branch panel", () => {
66	  it("test_lists_the_edits_in_the_order_they_were_made", () => {
67	    render(
68	      <BranchPanel
69	        branches={[STRIKE]}
70	        openId={STRIKE.id}
71	        world={WORLD}
72	        onOpen={vi.fn()}
73	        onFork={vi.fn()}
74	        naming={false}
75	        onNaming={vi.fn()}
76	      />,
77	    );
78	    const numbered = screen.getAllByText(/^[123]$/).map((one) => one.textContent);
79	    expect(numbered).toEqual(["1", "2", "3"]);
80	    expect(screen.getByText("Supposed · Oct 1")).toBeInTheDocument();
81	    expect(screen.getByText("Added")).toBeInTheDocument();
82	    expect(screen.getByText("Supposed · Oct 2")).toBeInTheDocument();
83	  });
84	
85	  it("test_renders_only_interface_words", () => {
86	    const { container } = render(
87	      <BranchPanel
88	        branches={[STRIKE]}
89	        openId={STRIKE.id}
90	        world={WORLD}
91	        onOpen={vi.fn()}
92	        onFork={vi.fn()}
93	        naming={false}
94	        onNaming={vi.fn()}
95	      />,
96	    );
97	    const words = (container.textContent ?? "").toLowerCase();
98	    for (const code of CODE_NAMES) {
99	      expect(words).not.toContain(code);
100	    }
101	  });
102	
103	  it("test_an_unedited_map_says_where_its_numbers_came_from", () => {
