28	  type BranchView,
29	  branchesOf,
30	  FixtureWorldSource,
31	  type WorldSource,
32	  type WorldView,
33	} from "./world";
34	import { asOneSentence } from "./world/failures";
35	import { countInWords } from "./world/naming";
36	
37	/**
38	 * Everything the screen can know about one thing it asked for. Three states and
39	 * no others, which is what makes every pixel below traceable to a cause.
40	 */
41	type Answer<Reading> =
42	  | { state: "asking" }
43	  | { state: "answered"; value: Reading }
44	  | { state: "failed"; reason: string };
45	
46	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
47	type Tone = "good" | "quiet" | "loud";
48	
49	/** One row of the strip at the foot of the launchpad. */
50	interface Reading {
51	  /** What is being reported, such as "server". */
52	  label: string;
53	  /** The value from the server, or null while the request is still in flight. */
54	  value: string | null;
55	  /** A mark beside the words. Never the only carrier of meaning. */
56	  glyph: string;
57	  /** What the value means, in plain words. On a failure, this is the failure. */
58	  state: string;
59	  tone: Tone;
60	}
61	
62	/**
63	 * Ask what this copy can do.
64	 *
65	 * Defined at module level because the hook below runs it once and needs the
66	 * same function on every render.
67	 *
68	 * **It reads the generated description of the server and nothing else.** The
69	 * two fields the first screen lives on — which examples can be played, and one
70	 * sentence per recording this engine could not read — were written out by hand
71	 * here for as long as the route that owns them was being built beside this
72	 * half. They are in `schema.ts` now, so the hand-written copy is gone: two
73	 * descriptions of one answer eventually disagree, and the generated one is the
74	 * server's own.
75	 */
76	function askReadiness(): Promise<Readiness> {
77	  return readReadiness();
78	}
79	
80	/**
81	 * Make one request when the screen first appears and report where it got to.
82	 *
83	 * @param ask The request to make. It must be the same function on every render,
84	 *   so pass one defined at module level rather than one written inline.
85	 */
86	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
87	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
88	
89	  useEffect(() => {
90	    let stillOnScreen = true;
91	    ask().then(
92	      (value) => {
93	        if (stillOnScreen) {
94	          setAnswer({ state: "answered", value });
95	        }
96	      },
97	      (reason: unknown) => {
98	        if (stillOnScreen) {
99	          setAnswer({ state: "failed", reason: asOneSentence(reason) });
100	        }
101	      },
102	    );
103	    return () => {
104	      stillOnScreen = false;
105	    };
106	  }, [ask]);
107	
108	  return answer;
109	}
110	
111	/** The row that says whether the server answered at all. */
112	function serverReading(answer: Answer<Health>): Reading {
113	  switch (answer.state) {
114	    case "asking":
115	      return {
116	        label: "server",
117	        value: null,
118	        glyph: "○",
119	        state: "asking the server",
120	        tone: "quiet",
121	      };
122	    case "answered":
123	      return {
124	        label: "server",
125	        value: answer.value.status,
126	        glyph: "●",
127	        state: "reachable",
128	        tone: "good",
129	      };
130	    case "failed":
131	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
132	  }
133	}
134	
135	/** The row that says whether a key for the language model is configured. */
136	function modelKeyReading(answer: Answer<Readiness>): Reading {
137	  switch (answer.state) {
138	    case "asking":
139	      return {
140	        label: "model key",
141	        value: null,
142	        glyph: "○",
143	        state: "asking the server",
144	        tone: "quiet",
145	      };
146	    case "answered":
147	      return answer.value.model_key_present
148	        ? {
149	            label: "model key",
150	            value: "present",
151	            glyph: "●",
152	            state: "ready to generate",
153	            tone: "good",
154	          }
155	        : {
156	            label: "model key",
157	            value: "absent",
158	            glyph: "○",
159	            state:
160	              answer.value.replayable.length === 0
161	                ? "no key configured, and nothing recorded to play instead"
162	                : `no key configured — ${countInWords(answer.value.replayable.length)} ` +
163	                  `${answer.value.replayable.length === 1 ? "example plays" : "examples play"} ` +
164	                  `from recordings`,
165	            tone: "quiet",
166	          };
167	    case "failed":
168	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
169	  }
170	}
171	
172	/** The row that says which build answered. */
173	function versionReading(answer: Answer<About>): Reading {
174	  switch (answer.state) {
175	    case "asking":
176	      return {
177	        label: "version",
178	        value: null,
179	        glyph: "○",
180	        state: "asking the server",
181	        tone: "quiet",
182	      };
183	    case "answered":
184	      return {
185	        label: "version",
186	        value: answer.value.version,
187	        glyph: "●",
188	        state: `reported by ${answer.value.name}`,
189	        tone: "good",
190	      };
191	    case "failed":
192	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
